    "id": "VSIPEM-2012-GT11-009",
    "title": "A HERMENÊUTICA DE PROFUNDIDADE E SUAS POSSIBILIDADES PARA A EDUCAÇÃO MATEMÁTICA",
    "abstract": "Apresentamos neste texto os pressupostos da metodologia da Hermenêutica de Profundidade (HP), bem como as suas potencialidades e possibilidades para pesquisas em Educação Matemática. Essa metodologia proposta para o estudo das formas simbólicas é composta de três movimentos analíticos: sócio-histórico, formal e interpretação/reinterpretação. Dessa forma, além de destacar a metodologia em si, pretendemos apresentar como alguns educadores matemáticos têm mobilizado esse método para analisar diferentes fontes, como: livros didáticos e não didáticos; teses de doutoramento e documentos oficiais. Enfocamos trabalhos desenvolvidos por membros do Grupo de História Oral e Educação Matemática (GHOEM) e seus interlocutores.",
