    "id": "VSIPEM-2012-GT10-034",
    "title": "AS PREMISSAS E OS PRESSUPOSTOS NA CONSTRUÇÃO CONCEITUAL DE MODELOS",
    "abstract": "A concepção de modelagem matemática como uma construção conceitual elaborada por meio da adoção de premissas e formulação de pressupostos utilizando a linguagem matemática, oferece uma lente para um entendimento dos papéis de modelos em atividades socioculturais. Este ensaio apresenta essa concepção de modelagem, ilustrando-a com o modelo galileano de queda livre com intuito de exemplificar a conceituação de um número limitado de aspectos da construção do modelo, que chamamos de isolado, destacando as premissas e os pressupostos que são fundamentais para sua construção.",
