    "id": "VSIPEM-2012-GT03-044",
    "title": "CONSTRUTIVISMO NO ENSINO DE FUNÇÕES TRIGONOMÉTRICAS: LIMITES E POSSIBILIDADES",
    "abstract": "Este artigo é produto de nossa pesquisa de mestrado, intitulada “Uma trajetória hipotética de aprendizagem sobre funções trigonométricas numa perspectiva construtivista”. Para fundamentar nossa pesquisa, utilizamos autores como Coll e Solé (2009) que defendem a perspectiva construtivista, e a formulações de Martin Simon (1995), que retoma aspectos da perspectiva construtivista de aprendizagem para apresentar a(s) Trajetória(s) Hipotética(s) de Aprendizagem (THA). Apoiamo-nos nas ideias de Pedro Gómez e José Luis Lupiáñez (2007), sobre o interesse de diferentes pesquisadores no uso de THA e inspirados pelas concepções de Zeichner (1998) que faz crítica à distância das pesquisas desenvolvidas na academia e o uso dos seus resultados nas salas de aula. A investigação teve como objetivos: discutir como compatibilizar perspectivas construtivistas de aprendizagem com o planejamento do ensino de Funções Trigonométricas; propor estratégias de articular os resultados obtidos com as pesquisas na área de Educação Matemática com a atuação do atuação do professor. Os resultados obtidos indicaram que o uso de pesquisas contribuiu para a organização do ensino; porém a sequência de ensino não é suficiente para garantir que a postura construtivista seja adotada pelo docente, pois a atuação do professor tem papel decisivo na construção do conhecimento dos seus alunos.",
    "edition": 5,
    "year": 2012,
    "gt": "GT03",
    "section": "GT03 — Educação Matemática no Ensino Médio",
