    "id": "VSIPEM-2012-GT05-053",
    "title": "DESCREVENDO UMA PRÁTICA MATEMATICAMENTE: UMA POSSIBILIDADE ETNOGRÁFICA PARA A ETNOMATEMÁTICA.",
    "abstract": "Este artigo, no rastro das discussões da tese de doutorado “Etnomatemática: do ôntico ao ontológico” (MIARKA, 2011), visa discutir a descrição de uma prática em etnomatemática sem separar descritor da prática que é descrita. Para isso, ao invés de buscar pela matemática em uma prática, defendemos a ideia de descrever uma prática matematicamente. Além disso, apontamos qual seria o papel do pesquisador em Etnomatemática nessa visão, assim como um caminho metodológico baseado na metodologia de Interrogação Mútua de Alangui (2006).",
