    "id": "VSIPEM-2012-GT11-055",
    "title": "DISPOSITIVO EXPERIMENTOTECA DE MATEMÁTICA: PRODUÇÃO NA IMANÊNCIA",
    "abstract": "O presente trabalho é fruto de uma pesquisa de Iniciação Científica (IC) que tem a intenção investigar como são potencializados os modos de subjetivação e de experimentação através do dispositivo Experimentoteca de Matemática. Tal dispositivo foi acionado durante os encontros entre bolsistas de um projeto de Treinamento Profissional e escolares de uma escola da rede pública de Juiz de Fora. A pesquisa busca cartografar as linhas de fuga que foram potencializadas durante a produção matemática nas atividades propostas no projeto. Dessa forma, a pesquisa lança olhares para a ligação entre a aprendizagem matemática e os modos de subjetivação potencializados no aprender, ou seja, atenta-se para a seguinte noção: quando o escolar produz matemática também é produzido por ela. Uma educação matemática na imanência do viver.",
