    "id": "VSIPEM-2012-GT06-076",
    "title": "KLOGO: PROFESSORES E A (RE)CONSTRUÇÃO DO PARALELOGRAMO",
    "abstract": "A questão principal de pesquisa consiste em determinar se e como conceitos de paralelogramos são (re)construídos por professores de matemática do 6° ao 9° ano do Ensino Fundamental, participantes de uma ação de formação, ao realizar atividades com o software Klogo. O software Klogo está disponível nos laptops distribuídos nas escolas contempladas pelo PROUCA (Projeto um Computador por Aluno). A ação de formação foi estruturada em encontros presencias e virtuais. Para a produção deste artigo usou-se registros realizados por um dos participantes do curso. O referencial teórico da pesquisa são os estudos realizados por Valente (1997; 2003; 2005), que trata do ciclo de ações e a espiral da aprendizagem. Estes estudos nos permitem compreender o papel do computador na construção de conhecimentos. A análise dos dados mostra que ao realizar atividades com o software Klogo, o sujeito da pesquisa (re)construiu o conceito de paralelogramo ao mobilizar conhecimentos de ângulos suplementares, alternos internos e alternos externos, na construção de um paralelogramo. A análise também evidencia a importância do papel do formador.",
    "edition": 5,
    "year": 2012,
    "gt": "GT06",
    "section": "GT06 — Educação Matemática: novas tecnologias e Educação à distância",
    "type": "Trabalho",
    "pages": "",
    "language": "pt-BR",
