    "id": "VSIPEM-2012-GT10-088",
    "title": "O DISCURSO REGULATIVO NOS MATERIAIS CURRICULARES EDUCATIVOS SOBRE MODELAGEM MATEMÁTICA",
    "abstract": "Neste artigo, nosso objetivo é analisar a mensagem contida nos materiais curriculares educativos sobre modelagem matemática, no que se refere a um discurso de ordem cujo objetivo é a organização social do contexto (discurso regulativo). A análise documental em uma abordagem qualitativa foi utilizada para analisar os materiais. Para tal propósito, usamos um instrumento analítico para explicitar modos como a mensagem regulativa pode estar explícita nos materiais curriculares educativos sobre modelagem matemática. Os dados sugerem que deixar explícito as regras do discurso regulativo nos materiais podem tornar visível às intenções pedagógicas dos elaboradores.",
