    "id": "VSIPEM-2012-GT11-106",
    "title": "O “PRO-JETO” PEDAGÓGICO EM FOCO: UM ENSAIO SOBRE O DEVIR DA FORMA-AÇÃO",
    "abstract": "Neste ensaio buscamos, por meio de um estudo bibliográfico, tecer considerações sobre nossa compreensão de pro-jeto, em especial de cursos de forma-ação de professores, e seu movimento de atualização. A tessitura do texto foi desenvolvida a partir de um viés filosófico, amparada nas ideias de Héráclito, Aristóteles e Heidegger.",
