    "id": "VSIPEM-2012-GT10-121",
    "title": "PRÁTICA PEDAGÓGICA E PESQUISA EM MODELAGEM NA EDUCAÇÃO MATEMÁTICA",
    "abstract": "O objetivo deste artigo é trazer reflexões sobre (e ressaltar a importância de) se explicitar tanto aspectos positivos quanto não-positivos de práticas de modelagem na educação matemática que servem como contextos para a realização de pesquisas nesse campo. Levantamos a hipótese de que um relato mais próximo da realidade escolar, em que experiências positivas e não-positivas co-existem, influenciando a realização de pesquisas e as reflexões sobre a prática, pode encurtar a distância entre prática e pesquisa. Para atingir o objetivo, apresentamos um referencial teórico que discute a dialética entre prática pedagógica e pesquisa e algumas reflexões sobre uma sequência de práticas pedagógicas e pesquisas realizadas pelos autores. Essas reflexões dão indícios de como essas duas atividades fazem parte de uma unidade única, se influenciam e se desenvolvem mutuamente, são diferentes, têm propósitos diferentes, podem ser incompatíveis, mas uma pressupõe e constitui a outra.",
