    "id": "VSIPEM-2012-GT08-137",
    "title": "SOBRE ANÁLISE DE CONTEÚDO, ANÁLISE TEXTUAL DISCURSIVA E ANÁLISE NARRATIVA: INVESTIGANDO PRODUÇÕES ESCRITAS EM MATEMÁTICA",
    "abstract": "Neste artigo realizamos uma discussão teórico-metodológica sobre Análise de Conteúdo, Análise Textual Discursiva e Análise Narrativa quando mobilizadas em análises de produções escritas de alunos. A partir de uma análise de algumas características, regulações e procedimentos utilizados nessas metodologias, apresentamos algumas semelhanças e diferenças entre esses modos de realizar análises de produções escritas.",
