    "id": "VSIPEM-2012-GT04-146",
    "title": "UMA SEQUÊNCIA DE ENSINO PARA A APLICAÇÃO DO TESTE DA HESSIANA",
    "abstract": "Investigações em torno do ensino/aprendizagem do Cálculo Diferencial a Várias Varáveis – CVV são registradas de forma escassa no Brasil. Neste estudo, apresenta-se uma Engenharia Didática – ED (ARTIGUE, 1995a, 1995b) com o tema envolvendo a identificação dos pontos extremantes de uma função z=f(x,y). A fase de experimentação e de validação da ED é apoiada nos pressupostos da metodologia de ensino conhecida no Ceará como Sequência Fedathi – SF. Deste modo, produziu-se um clima de investigação em uma atividade, na qual a exploração didática do software Maple se mostrou essencial com vista a se evitar sua algoritmização. A exploração das fases previstas pela SF proporcionou o emprego dos conhecimentos do CUV no contexto do CVV, o que fortalece o processo de transição interna (ALVES, 2011). Na fase de validação interna, registrou-se que os alunos confrontaram os dados obtidos por intermédio da visualização, segundo a identificação de pontos de inflexão e pontos críticos no r3 , com os dados obtidos pelas inferências lógicas. O uso do teste da Hessiana não se limitou ao modelo formal. Por fim, ante a complexidade dos símbolos algébricos do CVV, a mediação com recurso no software estimulou a interpretação intuitiva da tarefa e instalou o debate entre os alunos.",
    "edition": 5,
    "year": 2012,
    "gt": "GT04",
    "section": "GT04 — Educação Matemática no Ensino Superior",
    "type": "Trabalho",
